  nodos:
    por-host:                       # CASE HNAME dentro de los seriales 3246 y 3251
      ACYPGAMA: 10                  # Valle de México
      VDMBETA: 10
      ACYPOMEGA: 10
      MONALFA: 4                    # Monterrey
      CORDELTA: 12                  # Corporativo
      ACYPBETA: 32                  # solo con serial 3251
      VDMKAPPA: 4
    por-serial:
      "3247": 4                     # Monterrey Norte
      "473": 10
      "534": 10
      "866": 10
      "868": 10
      "2222": 10
    seriales-con-host: [3246, 3251] # si el host no está mapeado, NODO queda = serial

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
public class NodoResolver {

    private final NodosProperties p;

    /** Reproduce el CASE NODO de las líneas 1297-1320, incluido el caso sin ELSE interno. */
    public int resuelve(int serial, String hostname) {
        if (p.serialesConHost().contains(serial)) {
            return p.porHost().getOrDefault(hostname, serial);   // CASE HNAME sin ELSE
        }
        return p.porSerial().getOrDefault(String.valueOf(serial), 0);   // ELSE: NODO := 0 (inválido)
    }
}

@Configuration
@RequiredArgsConstructor
public class LineaS151FlowConfig {

    private final PasoComsFactory coms;         // SUBnnn: ENABLE PROGRAM vía COMS
    private final TaskExecutor paralelo;        // PROCESS = subrutina asíncrona en WFL

    @Bean
    Flow inicio(Step senalAperturaLinea,        // SUB612("ALINE")
                Step programarLote,             // SUB021
                Step p052, Step bajaP052,
                JobExecutionDecider teleton) {  // BANDERATELETON

        Flow[] asincronos = Stream.of("S15107", "S151P010", "S151P012", "S151P011", "S151P014",
                                      "S151P017", "S151P020", "S151P013", "S151P030", "S151P054")
                .map(prog -> new FlowBuilder<Flow>("alta-" + prog).start(coms.alta(prog)).build())
                .toArray(Flow[]::new);

        return new FlowBuilder<Flow>("INICIO")
                .start(senalAperturaLinea)
                .split(paralelo).add(asincronos)
                .next(coms.alta("S151P050"))
                .next(programarLote)
                .next(coms.alta("S151P053")).next(coms.alta("S151P055"))
                .next(coms.alta("S151P071")).next(coms.alta("S151P073"))
                .next(teleton)
                    .on("TELETON").to(bajaP052).next(p052)   // baja y vuelve a dar de alta P052
                .from(teleton).on("*").to(p052)
                .build();
    }
}

@Component
@RequiredArgsConstructor
public class DespachadorBajas {

    private final ComsControlAdapter coms;
    private final CalendarioBancario calendario;    // FESTIVO, SABADO, DOMINGO de S000P100
    private final BanderaTeleton teleton;
    private final SenalLinea senal;                 // SUB612

    /** En el WFL ("BAJAP030") : BAJAP050; se conserva detrás de una propiedad explícita. */
    @Value("${s151.linea.compat-bajap030-ejecuta-bajap050:true}")
    private boolean compatBajaP030;

    public void baja(AccionOperativa a) {
        switch (a) {
            case BAJAP030 -> coms.baja(compatBajaP030 ? "S151P050" : "S151P030");
            case BAJALINEA -> bajaLinea();
            default -> coms.baja(ProgramaComs.de(a));
        }
    }

    private void bajaLinea() {
        coms.baja("S151P011"); coms.baja("S151P030"); coms.baja("S151P050");
        if (calendario.hoyEsHabil()) {               // IF NOT (FESTIVO OR SABADO OR DOMINGO)
            coms.baja("S151P010"); coms.baja("S151P053");
        }
        coms.baja("S151P071"); coms.baja("S151P073");
        coms.baja("S151P054"); coms.baja("S151P055");
        senal.difunde("BLINE");
        if (!teleton.activa()) {
            coms.baja("S151P052");                   // con Teletón, P052 sigue arriba
        }
    }
}

/** FALLA(PNN): el operador elige R=reintento, T=termina, V=versión diferente. */
public enum DecisionFalla { REINTENTO, TERMINA, VERSION_DIFERENTE }

@Component
@RequiredArgsConstructor
public class PasoCargaArchivos implements Tasklet {      // SUB005 / S151P005

    private final ProgramaRunner runner;                 // RUN #S151P005 [T005]
    private final TituloResolver sacatit;                // SACATIT("S151P005CFIL")
    private final DecisionOperadorPort operador;         // reemplaza ACCEPT(MENSAJE)

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        String programa = sacatit.titulo("S151P005CFIL");
        while (true) {
            try {
                runner.run(programa, Map.of("taskfile",
                        "S151/TASKFILE/P005/" + ctx.getStepContext().getJobParameters().get("fechaYyMMdd")));
                return RepeatStatus.FINISHED;
            } catch (TaskFaultException e) {             // ON TASKFAULT
                var d = operador.decide("FALLA DE PASO 5", e);   // ticket o aprobación en consola
                switch (d.decision()) {
                    case TERMINA -> { return RepeatStatus.FINISHED; }   // GO BACKFORZA005
                    case VERSION_DIFERENTE -> programa = d.nuevoPrograma();
                    case REINTENTO -> { /* GO PASO005 */ }
                }
            }
        }
    }
}

public interface ComsControlAdapter {
    void alta(String programa);   // ENABLE PROGRAM
    void baja(String programa);   // DISABLE PROGRAM
}

/** Implementación destino: escalado del Deployment del servicio en Kubernetes. */
@Component
@RequiredArgsConstructor
class KubernetesControlAdapter implements ComsControlAdapter {

    private final AppsV1Api apps;
    private final ControlProperties props;   // s151.coms.programas.S15107.deployment: s151-p007

    @Override public void alta(String prog) { escala(prog, props.replicas(prog)); }
    @Override public void baja(String prog) { escala(prog, 0); }

    @Retryable(retryFor = ApiException.class, maxAttempts = Integer.MAX_VALUE,
               backoff = @Backoff(delay = 30_000))      // DO ... UNTIL TASKVALUE = 1
    void escala(String prog, int replicas) throws ApiException {
        var d = props.deployment(prog);
        apps.patchNamespacedDeploymentScale(d.nombre(), d.namespace(),
                new V1Patch("{\"spec\":{\"replicas\":" + replicas + "}}"))
            .execute();
        // WAIT ("DAR OK CUANDO *SYSTEM/COMS ESTE ACTIVO",OK) -> alerta a operación, no bloqueo
    }
}

