@Component
@RequiredArgsConstructor
public class ProgramadorLote {

    private final JobLauncher launcher;
    private final Job loteS151;               // S151/WFL/LOTE resuelto por SACATIT("S151LOTE")

    /** SUB021: se registra al dar INICIO; en el destino vive en el scheduler. */
    @Scheduled(cron = "${s151.lote.corresolo-p021.cron}", zone = "${s151.lote.corresolo-p021.zona}")
    void corresoloP021() throws Exception {
        launcher.run(loteS151, new JobParametersBuilder()
                .addString("parametro", "CORRESOLO P021")
                .addLocalDateTime("disparo", LocalDateTime.now())
                .toJobParameters());
    }
}

