# application.yml  (catálogo de plazas por nodo para REGISTRAS release 2)
s151:
  librerias:
    L002:
      origen: "S151/OBJECT/L002/REGISTRASNNN/{rel}MTP{mtp}"
      destino: "S151/OBJECT/L002/REGISTRAS{plaza}/{rel}MTP{mtp}"
      r2:
        nodo-10: ["084", "336", "408", "703", "711"]
        nodo-4:  ["087", "335", "408"]
        ambos: [32]              # NODO 32 o host ACYPBETA copian las dos listas

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
public class InstaladorL002 {

    private final LibreriasProperties props;
    private final ArtifactRepository repo;     // registro de artefactos (contenedor o JAR)

    public Set<String> plazasR2(int nodo, String host) {
        var r2 = props.l002().r2();
        boolean ambos = r2.ambos().contains(nodo) || "ACYPBETA".equals(host);
        var plazas = new LinkedHashSet<String>();          // evita copiar dos veces la 408
        if (nodo == 10 || ambos) plazas.addAll(r2.nodo10());
        if (nodo == 4  || ambos) plazas.addAll(r2.nodo4());
        return plazas;
    }

    public void instala(String rel, String mtp, int nodo, String host) {
        for (String plaza : plazasR2(nodo, host)) {
            repo.promueve(props.l002().origen(rel, mtp), props.l002().destino(plaza, rel, mtp));
        }
    }
}
